use std::alloc::{GlobalAlloc, Layout, System};
use std::sync::atomic::{AtomicUsize, Ordering::Relaxed};
use std::time::Instant;
use pine_runtime::{Bar, BarUpdate, HistoricalRuntime, RealtimeRuntime, OutputRetention};
use pine_sema::analyze_source;
use pine_syntax::{SourceFile, Severity};
use serde_json::json;

struct CountingAllocator;
static LIVE: AtomicUsize = AtomicUsize::new(0);
static ALLOCATED: AtomicUsize = AtomicUsize::new(0);
static ALLOCS: AtomicUsize = AtomicUsize::new(0);
unsafe impl GlobalAlloc for CountingAllocator {
    unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
        let p = unsafe { System.alloc(layout) };
        if !p.is_null() { LIVE.fetch_add(layout.size(), Relaxed); ALLOCATED.fetch_add(layout.size(), Relaxed); ALLOCS.fetch_add(1, Relaxed); }
        p
    }
    unsafe fn dealloc(&self, p: *mut u8, layout: Layout) {
        LIVE.fetch_sub(layout.size(), Relaxed);
        unsafe { System.dealloc(p, layout) }
    }
    unsafe fn realloc(&self, p: *mut u8, layout: Layout, size: usize) -> *mut u8 {
        let q = unsafe { System.realloc(p, layout, size) };
        if !q.is_null() { LIVE.fetch_add(size, Relaxed); LIVE.fetch_sub(layout.size(), Relaxed); ALLOCATED.fetch_add(size, Relaxed); ALLOCS.fetch_add(1, Relaxed); }
        q
    }
}
#[global_allocator] static GLOBAL: CountingAllocator = CountingAllocator;
fn bar(i: usize) -> Bar { let x=100.0+(i%17) as f64/16.0; Bar {time:1700000000+i as i64*60,open:x, high:x+1.0,low:x-1.0,close:x+0.25,volume:100.0} }
fn median(v: &mut [f64]) -> f64 {v.sort_by(f64::total_cmp); v[v.len()/2]}
fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<String> = std::env::args().collect();
    let source_text = std::fs::read_to_string(&args[1])?;
    let n: usize = args[2].parse()?;
    let mode=args.get(3).map(String::as_str).unwrap_or("historical");
    let source=SourceFile::new("probe.pine",source_text);
    let analysis=analyze_source(&source);
    if analysis.diagnostics.iter().any(|d|d.severity==Severity::Error) {return Err(format!("{:?}", analysis.diagnostics).into());}
    let hir=analysis.hir.ok_or("no hir")?;
    let initial=LIVE.load(Relaxed);
    if mode=="historical" {
        let mut runtime=HistoricalRuntime::new(&hir);
        let initial_allocated=ALLOCATED.load(Relaxed);
        let initial_allocations=ALLOCS.load(Relaxed);
        let started=Instant::now();
        for i in 0..n {runtime.append_bar(bar(i)).map_err(|e|e.message)?;}
        let seed_ms=started.elapsed().as_secs_f64()*1000.0;
        let seed_allocated=ALLOCATED.load(Relaxed)-initial_allocated;
        let seed_allocations=ALLOCS.load(Relaxed)-initial_allocations;
        let retained=LIVE.load(Relaxed)-initial;
        let profile=runtime.profile();
        let mut times=[0.0;31]; let mut clone_bytes=0; let mut clone_allocs=0;
        for t in &mut times {let live=LIVE.load(Relaxed); let count=ALLOCS.load(Relaxed); let started=Instant::now(); let copy=std::hint::black_box(runtime.clone()); *t=started.elapsed().as_secs_f64()*1000.0; clone_bytes=LIVE.load(Relaxed)-live;clone_allocs=ALLOCS.load(Relaxed)-count;drop(copy);}
        let live=LIVE.load(Relaxed); let started=Instant::now(); let result=runtime.result(); let result_ms=started.elapsed().as_secs_f64()*1000.0; let result_bytes=LIVE.load(Relaxed)-live;
        println!("{}",json!({"mode":mode,"bars":n,"script":args[1],"retainedHeapBytes":retained,"seedMs":seed_ms,"seedAllocatedBytes":seed_allocated,"seedAllocations":seed_allocations,"rollingWindowValues":profile.rolling_window_values,"rollingWindowValueCapacity":profile.rolling_window_value_capacity,"seriesValues":profile.series_values,"matrixSlots":profile.matrix_slots,"matrixCells":profile.matrix_cells,"arraySlots":profile.array_slots,"arrayValues":profile.array_values,"cloneHeapBytes":clone_bytes,"cloneAllocations":clone_allocs,"cloneMedianMs":median(&mut times),"resultHeapBytes":result_bytes,"resultMs":result_ms,"plotValues":profile.plot_values}));
        std::hint::black_box(result);
    } else {
        let mut runtime=RealtimeRuntime::new(&hir);
        if mode=="retained" {runtime.set_output_retention(OutputRetention::keep_confirmed_bars(64));}
        let bars:Vec<_>=(0..n).map(bar).collect();
        drop(runtime.seed_historical(&bars).map_err(|e|e.message)?);drop(bars);
        let retained=LIVE.load(Relaxed)-initial;
        let mut diff_ms=[0.0;31]; let mut diff_bytes=[0usize;31];
        let mut full_ms=[0.0;31]; let mut full_bytes=[0usize;31];
        for i in 0..31 {
            let prior=ALLOCATED.load(Relaxed);let start=Instant::now();let changes=runtime.apply_update(BarUpdate::forming(bar(n))).map_err(|e|e.message)?; diff_ms[i]=start.elapsed().as_secs_f64()*1000.0;diff_bytes[i]=ALLOCATED.load(Relaxed)-prior;drop(changes);
            let prior=ALLOCATED.load(Relaxed);let start=Instant::now();let result=runtime.update(BarUpdate::forming(bar(n))).map_err(|e|e.message)?;full_ms[i]=start.elapsed().as_secs_f64()*1000.0;full_bytes[i]=ALLOCATED.load(Relaxed)-prior;drop(result);
        }
        diff_bytes.sort();full_bytes.sort();
        println!("{}",json!({"mode":mode,"bars":n,"script":args[1],"retainedHeapBytes":retained,"applyUpdateMedianMs":median(&mut diff_ms),"updateMedianMs":median(&mut full_ms),"applyAllocatedMedianBytes":diff_bytes[15],"updateAllocatedMedianBytes":full_bytes[15],"seriesValues":runtime.profile().series_values,"matrixSlots":runtime.profile().matrix_slots}));
    }
    Ok(())
}

